pattern.example:
# Redis key patterns for profile data: # - profile:{user_id} - Cached profile data (JSON, TTL: 900s = 15 min) # - profile_meta:{user_id} - Metadata hash (message_count, last_refresh) (TTL: 86400s = 24h)
# Pattern: Loading from cache async def load_profile_from_cache(self, user_id: str) -> Dict[str, Any]: cache_key = f"profile:{user_id}" cached_data = await self.redis_client.get(cache_key)
if cached_data: profile = json.loads(cached_data) profile["cached"] = True return profile else: # Return empty profile return { "user_id": user_id, "completeness": 0, "cached": False, "basics": {}, "preferences": {}, # ... }
# Profile structure includes: # { # "user_id": "123456", # "completeness": 45, # "basics": {"name": "Sarah", "timezone": "US/Pacific", ...}, # "preferences": {"communication_style": "direct", ...}, # "goals": {...}, # "interests": {...}, # "background": {...} # }

from dataclasses import dataclass
from typing import Optional
from datetime import datetime

@dataclass
class GateResult:
    """Result from subconscious gate check."""
    allowed: bool
    reason: Optional[str] = None
    defer_until: Optional[datetime] = None

# Usage:
return GateResult(allowed=False, reason="recent_contact")
return GateResult(allowed=True)
return GateResult(
    allowed=False,
    reason="quiet_hours",
    defer_until=datetime(2025, 12, 25, 8, 0, 0, tzinfo=user_tz)
)

import pytest from unittest.mock import AsyncMock from datetime import datetime, timezone
@pytest.fixture async def redis_mock(): """Mock Redis client.""" mock = AsyncMock() mock.get = AsyncMock() mock.setex = AsyncMock() mock.incr = AsyncMock() mock.expire = AsyncMock() mock.close = AsyncMock() return mock
@pytest.fixture async def gate_manager(redis_mock): """SubconsciousGate instance with mocked Redis.""" from api.proactive.gate import SubconsciousGate gate = SubconsciousGate(redis_client=redis_mock) return gate
@pytest.mark.asyncio async def test_recent_contact_blocks(gate_manager, redis_mock): """Test gate blocks when user messaged recently.""" user_id = "test_user_123"
# Mock session with recent last_activity (30 minutes ago) recent_time = datetime.now(timezone.utc) - timedelta(minutes=30) session = { "user_id": user_id, "last_activity": recent_time.isoformat().replace("+00:00", "Z") } redis_mock.get.return_value = json.dumps(session)
result = await gate_manager.check_gate(user_id)
assert result.allowed == False assert result.reason == "recent_contact" redis_mock.get.assert_called_once_with(f"session:{user_id}")

logging_guidance.code:
# Log gate decisions for debugging
logger.info(
    "Subconscious gate check",
    extra={
        "user_id": user_id,
        "allowed": result.allowed,
        "reason": result.reason,
        "defer_until": result.defer_until.isoformat() if result.defer_until else None
    }
)

# Log individual check failures
logger.debug(
    "Recent contact check blocked",
    extra={
        "user_id": user_id,
        "last_activity": last_activity_str,
        "hours_since": hours_since
    }
)
